from pathlib import Path
import difflib,subprocess
R=Path.cwd();A=R/'artifacts/crow-v15-teacher-contact-alias-fix-20261110';B=R/'build/crow-v15-teacher-contact-alias-fix-20261110';F=R/'artifacts/crow-v15-flight-feedback-freeze-20261110';old=(R/'build/crow-v15-heavy-wing-teacher-route-20261110/teacher.metal').read_text();s=old
changes=[('const float4 oracleCommand = privilegedCommand ? state.nutrition : actorCommand;','''// Foot support occupies nutrition.xy at the accepted-state boundary.\n        // In teacher mode, pack two millimetre-per-second-resolution commands\n        // into nutrition.z; heading is already published in commandExtension.x.\n        const float encoded = floor(max(state.nutrition.z,0.0f) + 0.5f);\n        const float lateralMilli = floor(encoded / 1024.0f);\n        const float forwardMilli = encoded - 1024.0f * lateralMilli;\n        const float4 teacherCommand = float4(forwardMilli * 0.001f - 0.25f,\n            lateralMilli * 0.001f - 0.30f, state.commandExtension.x, state.nutrition.w);\n        const float4 oracleCommand = privilegedCommand ? teacherCommand : actorCommand;'''),('state.nutrition=float4(0.25f-errorOffset,desiredLateral,-heading,desiredHeight);','''const float forward = clamp(0.25f-errorOffset,-0.25f,0.75f);\n            const float lateral = clamp(desiredLateral,-0.30f,0.30f);\n            const float encoded = round((forward+0.25f)*1000.0f) +\n                1024.0f * round((lateral+0.30f)*1000.0f);\n            state.nutrition=float4(0.0f,0.0f,encoded,desiredHeight);'''),('clamp((state.nutrition.x-0.10f)/0.30f,-1.0f,1.0f),\n                clamp(state.nutrition.y/0.30f,-1.0f,1.0f),\n                clamp(state.nutrition.z/0.15f,-1.0f,1.0f),\n                clamp((state.nutrition.w-0.975f)/0.325f,-1.0f,1.0f)', 'clamp((teacherCommand.x-0.10f)/0.30f,-1.0f,1.0f),\n                clamp(teacherCommand.y/0.30f,-1.0f,1.0f),\n                clamp(teacherCommand.z/0.15f,-1.0f,1.0f),\n                clamp((teacherCommand.w-0.975f)/0.325f,-1.0f,1.0f)'),('0.3506562412f,0.00001f,0.00001f,0.00001f,0.00001f,0.0001406249939f,0.0001406249939f','0.27945411f,0.00001f,0.00001f,0.00001f,0.00001f,0.03574169055f,0.03574169055f')]
for a,b in changes:assert s.count(a)==1,(a[:90],s.count(a));s=s.replace(a,b)
(B/'teacher.metal').write_text(s);(A/'teacher.patch').write_text(''.join(difflib.unified_diff(old.splitlines(True),s.splitlines(True),fromfile='a/teacher-alias.metal',tofile='b/teacher-isolated.metal')));subprocess.run(['xcrun','-sdk','macosx','metal','-std=metal4.0','-O3','-fno-fast-math','-I',str(F),'-I',str(R/'include'),'-I',str(R/'src/metal'),'-c',str(B/'teacher.metal'),'-o',str(B/'teacher.air')],check=True);other=sorted(p for p in (R/'build/shaders').glob('MetalRobo*.air') if p.name not in ('MetalRoboLocomotionTask.air','MetalRoboFlappingWingDynamics.air'));subprocess.run(['xcrun','-sdk','macosx','metallib',*[str(x) for x in other],str(R/'build/crow-v15-wing-aero-alignment-20261110/aero.air'),str(B/'teacher.air'),'-o',str(B/'teacher.metallib')],check=True)
